-- Generated by model/lib/sql/generate.mjs. Loads IMPORT OPEX from cells/IMPORT OPEX.csv in the folder of input cells. Two rows for one cell add up.
INSERT OR REPLACE INTO "IMPORT OPEX" SELECT coalesce(k0."Cost Center", error('cells name a member Cost Center does not have: ' || c."Cost Center")), coalesce(k1."Account", error('cells name a member Account does not have: ' || c."Account")), coalesce(k2."Years", error('cells name a member Years does not have: ' || c."Years")), coalesce(k3."Months", error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE)
FROM read_csv('cells/IMPORT OPEX.csv', header = true, all_varchar = true) c LEFT JOIN "dim Cost Center" k0 ON k0.name = c."Cost Center" LEFT JOIN "dim Account" k1 ON k1.name = c."Account" LEFT JOIN "dim Years" k2 ON k2.name = c."Years" LEFT JOIN "dim Months" k3 ON k3.name = c."Months"
GROUP BY ALL;
